for path, expected_old, expected_new, text in SOURCE_CHANGES:
    p = Path(path)
    original = p.read_bytes()
    if blob_hash(original) != expected_old:
        raise RuntimeError("Refusing G1 patch: source baseline drifted: " + path)
    replacement = text.encode("utf-8")
    if blob_hash(replacement) != expected_new:
        raise RuntimeError("Refusing G1 patch: candidate source hash differs: " + path)
    if replacement == original:
        raise RuntimeError("Refusing G1 patch: no change: " + path)
    p.write_bytes(replacement)
    if blob_hash(p.read_bytes()) != expected_new:
        raise RuntimeError("Refusing G1 patch: failed read-back: " + path)
    print("G1 source verified:", path, expected_new)

print("G1 source patch applied; controlled publisher owns build, tests and checkpoint.")
